/* The tables of M29 · Appraisal and training. */

export const appraisalTemplates = defineTable(
  'appraisal_templates',
  { module: 'M29', scope: 'org' },
  {
    ...baseColumns,
    name: text().notNull(),
    staffType: enumText(appraisalTemplateStaffTypes).notNull(),
    scaleMax: integer().notNull().default(5),
    /** a label per point */
    scaleLabels: jsonb().notNull(),
    /** `{ key, title, weight, criteria: { key, label, hint? }[] }[]`; weights total 100 */
    sections: jsonb().notNull(),
    /** `{ from, label }[]` over the final percentage */
    ratingBands: jsonb().notNull(),
    isActive: boolean().notNull().default(true),
  },
  (t) => [
    between('appraisal_templates', t.scaleMax, 3, 10),
    uniqueIndex('appraisal_templates_name_uq').on(t.orgId, t.name).where(live(t)),
  ],
);

export const appraisalCycles = defineTable(
  'appraisal_cycles',
  { module: 'M29', scope: 'org' },
  {
    ...baseColumns,
    /** "Annual appraisal 2026–27" */
    name: text().notNull(),
    kind: enumText(appraisalCycleKinds).notNull(),
    periodFrom: dateStr().notNull(),
    periodTo: dateStr().notNull(),
    selfDueOn: dateStr().notNull(),
    managerDueOn: dateStr().notNull(),
    /** empty means all */
    branchIds: uuid()
      .array()
      .notNull()
      .default(sql`'{}'`),
    status: enumText(appraisalCycleStatuses).notNull().default('draft'),
  },
  (t) => [
    check('appraisal_cycles_period_to_after', sql`${t.periodTo} > ${t.periodFrom}`),
    check('appraisal_cycles_manager_due_on_from', sql`${t.managerDueOn} >= ${t.selfDueOn}`),
  ],
);

/** One per staff member per cycle. */
export const appraisalForms = defineTable(
  'appraisal_forms',
  { module: 'M29', scope: 'org' },
  {
    ...baseColumns,
    cycleId: uuid()
      .references((): AnyPgColumn => appraisalCycles.id)
      .notNull(),
    staffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    templateId: uuid()
      .references((): AnyPgColumn => appraisalTemplates.id)
      .notNull(),
    /** defaults to the reporting manager; not the appraisee */
    appraiserStaffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    /** the appraiser's manager */
    reviewerStaffId: uuid().references((): AnyPgColumn => staff.id),
    status: enumText(appraisalFormStatuses).notNull().default('self_pending'),
    selfSubmittedAt: timestamptz(),
    managerSubmittedAt: timestamptz(),
    finalPercent: decimal(5, 2),
    ratingLabel: text(),
    strengths: text(),
    improvements: text(),
    managerComment: text(),
    /** written on acknowledgement */
    staffComment: text(),
    recommendation: enumText(appraisalFormRecommendations).notNull().default('none'),
    sharedAt: timestamptz(),
    acknowledgedAt: timestamptz(),
  },
  (t) => [uniqueIndex('appraisal_forms_cycle_staff_uq').on(t.cycleId, t.staffId).where(live(t))],
);

export const appraisalScores = defineTable(
  'appraisal_scores',
  { module: 'M29', scope: 'org' },
  {
    ...baseColumns,
    formId: uuid()
      .references((): AnyPgColumn => appraisalForms.id)
      .notNull(),
    /** a key from the template */
    criterionKey: text().notNull(),
    /** 1 to the template's `scale_max` */
    selfScore: integer(),
    managerScore: integer(),
    /** set at review, defaults to the manager's */
    finalScore: integer(),
    comment: text(),
  },
  (t) => [
    uniqueIndex('appraisal_scores_form_criterion_key_uq')
      .on(t.formId, t.criterionKey)
      .where(live(t)),
  ],
);

